"""Module for defining the decoration of the dcap collector for emil on VRAN Testlines
"""
import logging
from taf.collectors.core import NamedComponentFactory, StartableCollector
from taf.collectors.core.entities.managed_coam_cu_connection import ManagedCoamCUConnection
from taf.collectors.core.entities.managed_vdu_connection import ManagedVduConnection
from taf.collectors.base import Decorating
from .dcap_starter import DcapStarterFactory
from .vdu_service_port_setter import VduServicePortSetter
from .vcu_service_port_setter import VcuServicePortSetter

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CloudGnbEmilCollector(
        Decorating,
        StartableCollector):
    """Decorating collector for the taf.collectors.dcap collector for emil logs for cloud gNB"""


class CloudGnbEmilCollectorFactory(NamedComponentFactory):
    """Factory for the decorating collector of collector for emil traces on vran"""
    _product_class = CloudGnbEmilCollector

    def __init__(self, **kwargs):
        super(CloudGnbEmilCollectorFactory, self).__init__(**kwargs)
        self._dcap_starter = None
        self._service_port_setter = None

    def create(self, configuration, existing_arguments=None):
        collector = super(CloudGnbEmilCollectorFactory, self).create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        collector.collector.add_prerequisite(self._dcap_starter)
        collector.collector.add_prerequisite(self._service_port_setter)
        return collector

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CloudGnbEmilCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        self._dcap_starter = self._create_dcap_starter(configuration)
        cloud_part = configuration["cloud_part"]
        if cloud_part == "cu":
            self._service_port_setter = self._create_vcu_service_port_setter(configuration)
        elif cloud_part == "vdu":
            self._service_port_setter = self._create_vdu_service_port_setter(configuration)
        else:
            raise AssertionError(f"unknown cloud_part: {cloud_part!r}")

    def _create_dcap_starter(self, configuration):
        return DcapStarterFactory().create(
            configuration={'executor': configuration['executor']},
            existing_arguments={})

    def _create_vcu_service_port_setter(self, configuration):
        vcu_connection = self._create_vcu_connection(oam_config=configuration["oam_config"])
        return VcuServicePortSetter(vcu_connection=vcu_connection)

    def _create_vdu_service_port_setter(self, configuration):
        vdu_connection = self._create_vdu_connection(oam_config=configuration["oam_config"])
        return VduServicePortSetter(vdu_connection=vdu_connection)

    def _create_vcu_connection(self, oam_config):
        return ManagedCoamCUConnection(
            cu_connection_params=oam_config)

    def _create_vdu_connection(self, oam_config):
        return ManagedVduConnection(
            vdu_connection_params=oam_config)
